/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    decodePlayerInfoSaveBytes
 * depends    src/node/decrypt-save, src/node/nrbf/reader, src/node/nrbf/to-json, src/node/types, src/save/access/json, src/save/battle/history
 * used by    src/calculators/specs.generated, src/node/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { gunzipSync } from 'node:zlib'
import { decryptSaveSync } from './decrypt-save'

import { listImportableBattleRuns } from '../save/battle/history'
import { readToolExportJson } from '../save/access/json'
import { NRBFReader } from './nrbf/reader'
import { nrbfToJSON } from './nrbf/to-json'
import type { PlayerInfoSaveDecodeResult } from './types'

function toUint8Array(input: Uint8Array | Buffer | ArrayBuffer): Uint8Array {
  if (input instanceof Uint8Array) {
    return input
  }
  if (Buffer.isBuffer(input)) {
    return new Uint8Array(input.buffer, input.byteOffset, input.byteLength)
  }
  return new Uint8Array(input)
}

function inflateIfGzip(bytes: Uint8Array): { inflated: Uint8Array; wasGzip: boolean } {
  const isGzip = bytes.length >= 2 && bytes[0] === 0x1f && bytes[1] === 0x8b
  if (!isGzip) {
    return { inflated: bytes, wasGzip: false }
  }
  const inflated = gunzipSync(Buffer.from(bytes))
  return { inflated: new Uint8Array(inflated), wasGzip: true }
}

/**
 * Decodes official JSON exports, legacy gzip/raw NRBF and TDS1 encrypted saves into one root shape.
 */
export function decodePlayerInfoSaveBytes(input: Uint8Array | Buffer | ArrayBuffer): PlayerInfoSaveDecodeResult {
  const bytes = decryptSaveSync(toUint8Array(input))
  const { inflated, wasGzip } = inflateIfGzip(bytes)
  const parsed = readToolExportJson(inflated) ?? nrbfToJSON(NRBFReader.readStream(inflated))
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error('Failed to decode playerInfo.dat: NRBF root was not an object')
  }
  const parsedRoot = parsed as Record<string, unknown>
  return {
    parsedRoot,
    wasGzip,
    battleRunCount: listImportableBattleRuns(parsedRoot).length,
  }
}
